INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 47, 'theory', 'Quiz: PostgreSQL and sqlx');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 47, 0, 'What is the right way to pass values into an SQL query in sqlx?', '["Insert them into the query text with format!", "Through $1, $2 parameters and the bind method", "By string concatenation", "Through environment variables"]', 1, 'Bound parameters travel separately from the query text and can never be mistaken for SQL commands.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 47, 1, 'What happens to an sqlx transaction if the Transaction object is dropped without commit?', '["The changes are applied", "The changes are rolled back", "The program exits", "The transaction hangs forever"]', 1, 'Without commit, the transaction rolls back when dropped, which is handy for an early exit on error.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 47, 2, 'Which SQLSTATE code means a uniqueness violation?', '["23503", "23505", "23514", "42P01"]', 1, '23505 is unique_violation; 23503 is a foreign key, 23514 is a check.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 47, 3, 'Why shouldn''t you hold a pool connection during a long external operation?', '["Connections are expensive and the pool is limited: a few slow operations will drain the pool", "The compiler forbids it", "The database closes the connection at once", "It speeds up queries"]', 0, 'The pool is small; held connections prevent other requests from being served.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 47, 4, 'Why is "messages before id N" pagination better than OFFSET?', '["It is shorter to write", "The index lets you jump straight to the right place, while OFFSET has to skip rows", "OFFSET is forbidden in PostgreSQL", "There is no difference"]', 1, 'A key-based query uses the index and does not slow down as the page number grows.');
